CREATE TABLE blocks (id varchar(64) PRIMARY KEY, name varchar(100) NOT NULL UNIQUE, contact_email varchar(254) NOT NULL DEFAULT '', contact_phone varchar(30) NOT NULL DEFAULT '', active boolean NOT NULL DEFAULT true);
CREATE TABLE messes (id varchar(64) PRIMARY KEY, name varchar(120) NOT NULL UNIQUE, capacity integer NOT NULL CHECK(capacity > 0), active boolean NOT NULL DEFAULT true);
CREATE TABLE mess_blocks (mess_id varchar(64) NOT NULL REFERENCES messes(id), block_id varchar(64) NOT NULL REFERENCES blocks(id), PRIMARY KEY(mess_id,block_id));
CREATE TABLE rooms (id varchar(64) PRIMARY KEY, block_id varchar(64) NOT NULL REFERENCES blocks(id), number varchar(20) NOT NULL, capacity integer NOT NULL CHECK(capacity > 0), room_type varchar(20) NOT NULL, active boolean NOT NULL DEFAULT true, UNIQUE(block_id,number));
CREATE TABLE users (id varchar(64) PRIMARY KEY, email varchar(254) NOT NULL UNIQUE, name varchar(150) NOT NULL, role varchar(30) NOT NULL CHECK(role IN ('ADMIN','DIRECTOR','WARDEN','SUPERVISOR','STUDENT','MESS_MANAGER','HOUSEKEEPING')), phone varchar(30) NOT NULL DEFAULT '', roll_no varchar(40) UNIQUE, block_id varchar(64) REFERENCES blocks(id), room_id varchar(64) REFERENCES rooms(id), mess_id varchar(64) REFERENCES messes(id), cloakroom_access boolean NOT NULL DEFAULT false, mess_change_access boolean NOT NULL DEFAULT false, active boolean NOT NULL DEFAULT true, created_at varchar(40) NOT NULL);
CREATE TABLE otp_guard (id integer PRIMARY KEY);
INSERT INTO otp_guard VALUES (1);
CREATE TABLE otp_requests (id varchar(64) PRIMARY KEY, email_hash varchar(64) NOT NULL, ip_hash varchar(64) NOT NULL, requested_at varchar(40) NOT NULL);
CREATE INDEX otp_rate_email ON otp_requests(email_hash,requested_at);
CREATE INDEX otp_rate_ip ON otp_requests(ip_hash,requested_at);
CREATE TABLE otp_challenges (user_id varchar(64) PRIMARY KEY REFERENCES users(id), code_hash varchar(64) NOT NULL, expires_at varchar(40) NOT NULL, attempts integer NOT NULL DEFAULT 0, consumed boolean NOT NULL DEFAULT false);
CREATE TABLE sessions (id varchar(64) PRIMARY KEY, user_id varchar(64) NOT NULL REFERENCES users(id), expires_at varchar(40) NOT NULL, revoked boolean NOT NULL DEFAULT false);
CREATE TABLE announcements (id varchar(64) PRIMARY KEY, title varchar(140) NOT NULL, body text NOT NULL, level varchar(20) NOT NULL, audience varchar(30) NOT NULL DEFAULT 'ALL', block_id varchar(64) REFERENCES blocks(id), active boolean NOT NULL DEFAULT true, created_by varchar(64) NOT NULL REFERENCES users(id), created_at varchar(40) NOT NULL);
CREATE TABLE menus (id varchar(64) PRIMARY KEY, mess_id varchar(64) NOT NULL REFERENCES messes(id), weekday varchar(10) NOT NULL, breakfast text NOT NULL, lunch text NOT NULL, snacks text NOT NULL, dinner text NOT NULL, updated_at varchar(40) NOT NULL, UNIQUE(mess_id,weekday));
CREATE TABLE feedback (id varchar(64) PRIMARY KEY, student_id varchar(64) NOT NULL REFERENCES users(id), block_id varchar(64) NOT NULL REFERENCES blocks(id), mess_id varchar(64) NOT NULL REFERENCES messes(id), meal varchar(20) NOT NULL, meal_date varchar(10) NOT NULL, rating integer NOT NULL CHECK(rating BETWEEN 1 AND 5), comment text NOT NULL, reply text NOT NULL DEFAULT '', created_at varchar(40) NOT NULL, UNIQUE(student_id,mess_id,meal,meal_date));
CREATE TABLE polls (id varchar(64) PRIMARY KEY, mess_id varchar(64) NOT NULL REFERENCES messes(id), title varchar(200) NOT NULL, closes_at varchar(40) NOT NULL, created_at varchar(40) NOT NULL);
CREATE TABLE poll_options (id varchar(64) PRIMARY KEY, poll_id varchar(64) NOT NULL REFERENCES polls(id), label varchar(140) NOT NULL);
CREATE TABLE votes (poll_id varchar(64) NOT NULL REFERENCES polls(id), student_id varchar(64) NOT NULL REFERENCES users(id), option_id varchar(64) NOT NULL REFERENCES poll_options(id), block_id varchar(64) NOT NULL REFERENCES blocks(id), created_at varchar(40) NOT NULL, PRIMARY KEY(poll_id,student_id));
CREATE TABLE outings (id varchar(64) PRIMARY KEY, student_id varchar(64) NOT NULL REFERENCES users(id), block_id varchar(64) NOT NULL REFERENCES blocks(id), kind varchar(20) NOT NULL, destination varchar(200) NOT NULL, reason text NOT NULL, departure_at varchar(40) NOT NULL, expected_return_at varchar(40) NOT NULL, status varchar(20) NOT NULL, decision_note text NOT NULL DEFAULT '', decided_by varchar(64) REFERENCES users(id), exited_at varchar(40), entered_at varchar(40), created_at varchar(40) NOT NULL);
CREATE INDEX outings_student_status ON outings(student_id,status);
CREATE TABLE discipline (id varchar(64) PRIMARY KEY, student_id varchar(64) NOT NULL REFERENCES users(id), block_id varchar(64) NOT NULL REFERENCES blocks(id), violation varchar(200) NOT NULL, action_taken varchar(500) NOT NULL, notes text NOT NULL, occurrence_number integer NOT NULL, card_held boolean NOT NULL DEFAULT false, card_returned_at varchar(40), return_notes text NOT NULL DEFAULT '', created_by varchar(64) NOT NULL REFERENCES users(id), created_at varchar(40) NOT NULL);
CREATE TABLE storage_rooms (id varchar(64) PRIMARY KEY, block_id varchar(64) NOT NULL REFERENCES blocks(id), name varchar(120) NOT NULL, capacity integer NOT NULL CHECK(capacity > 0), active boolean NOT NULL DEFAULT true, UNIQUE(block_id,name));
CREATE TABLE cloakroom (id varchar(64) PRIMARY KEY, receipt varchar(64) NOT NULL UNIQUE, student_id varchar(64) NOT NULL REFERENCES users(id), block_id varchar(64) NOT NULL REFERENCES blocks(id), storage_id varchar(64) NOT NULL REFERENCES storage_rooms(id), item varchar(30) NOT NULL, item_condition varchar(30) NOT NULL, notes text NOT NULL, status varchar(20) NOT NULL, submitted_by varchar(64) NOT NULL REFERENCES users(id), submitted_at varchar(40) NOT NULL, returned_by varchar(64) REFERENCES users(id), returned_at varchar(40));
CREATE INDEX cloakroom_student_status ON cloakroom(student_id,status);
CREATE TABLE maintenance (id varchar(64) PRIMARY KEY, student_id varchar(64) REFERENCES users(id), block_id varchar(64) NOT NULL REFERENCES blocks(id), room_label varchar(40) NOT NULL, category varchar(40) NOT NULL, description text NOT NULL, assignee_id varchar(64) REFERENCES users(id), status varchar(20) NOT NULL, resolution text NOT NULL DEFAULT '', created_at varchar(40) NOT NULL, updated_at varchar(40) NOT NULL);
CREATE TABLE mess_changes (id varchar(64) PRIMARY KEY, student_id varchar(64) NOT NULL REFERENCES users(id), block_id varchar(64) NOT NULL REFERENCES blocks(id), mess_id varchar(64) NOT NULL REFERENCES messes(id), status varchar(20) NOT NULL, decision_note text NOT NULL DEFAULT '', created_at varchar(40) NOT NULL);
CREATE TABLE audit (id varchar(64) PRIMARY KEY, actor_id varchar(64) NOT NULL REFERENCES users(id), action varchar(100) NOT NULL, resource_type varchar(40) NOT NULL, resource_id varchar(64) NOT NULL, block_id varchar(64) REFERENCES blocks(id), detail text NOT NULL, created_at varchar(40) NOT NULL);
CREATE INDEX audit_created ON audit(created_at);
